parameters.jsCode:
const item = $input.first().json;

const critical = item.critical || [];
const warning = item.warning || [];
const hearings = item.hearings || [];

const auditReport = {
  timestamp: new Date().toISOString(),
  workflow: 'auditoria-terminos',
  criticos: critical.map(t => ({
    caso: t.title,
    numero: t.case_number,
    vencido: true
  })),
  porVencer: warning.map(t => ({
    caso: t.title,
    numero: t.case_number
  })),
  audienciasHoy: hearings.map(h => ({
    caso: h.case_title,
    numero: h.case_number
  })),
  resumen: {
    totalCriticos: critical.length,
    totalPorVencer: warning.length,
    totalAudiencias: hearings.length,
    requiereAccion: critical.length > 0
  }
};

return [{
  json: auditReport
}];

